DROP SCHEMA IF EXISTS t2s_xshort CASCADE;
CREATE SCHEMA t2s_xshort;
CREATE VIEW t2s_xshort.tb_brnch AS SELECT branch_id AS brnch_id, branch_code AS brnch_code, branch_name AS brnch_name, branch_type AS brnch_type, parent_branch_id AS prnt_brnch_id, province AS prvnc, district AS dstrc, opened_date AS opnd_date, closed_date AS clsd_date, is_active AS is_actv FROM t2s.branches;
CREATE VIEW t2s_xshort.tb_emply AS SELECT employee_id AS emply_id, employee_no AS emply_no, first_name AS frst_name, last_name AS last_name, full_name AS full_name, branch_id AS brnch_id, department_code AS dprtm_code, department_name AS dprtm_name, position_code AS pstn_code, position_name AS pstn_name, manager_id AS mngr_id, hire_date AS hire_date, termination_date AS trmnt_date, employment_status AS emply_stts FROM t2s.employees;
CREATE VIEW t2s_xshort.tb_cstmr AS SELECT customer_id AS cstmr_id, customer_number AS cstmr_nmbr, customer_name AS cstmr_name, party_type AS prty_type, customer_type_code AS cstmr_type_code, customer_type_name AS cstmr_type_name, status_code AS stts_code, status_name AS stts_name, segment_code AS sgmnt_code, segment_name AS sgmnt_name, branch_id AS brnch_id, relationship_manager_id AS rltns_mngr_id, kyc_status AS kyc_stts, aml_status AS aml_stts, risk_level AS risk_lvl, is_pep AS is_pep, is_blacklisted AS is_blckl, is_resident AS is_rsdnt, country_code AS cntry_code, onboarded_date AS onbrd_date, closed_date AS clsd_date, province AS prvnc, district AS dstrc FROM t2s.customers;
CREATE VIEW t2s_xshort.tb_indvd AS SELECT customer_id AS cstmr_id, gender AS gndr, birth_year AS brth_year, age AS age, marital_status AS mrtl_stts, dependants_count AS dpndn_cnt, education_level AS edctn_lvl, occupation AS occpt, employer_name AS emply_name, employment_type AS emply_type, monthly_income AS mnthl_incm, income_currency AS incm_crrnc FROM t2s.individuals;
CREATE VIEW t2s_xshort.tb_orgnz AS SELECT customer_id AS cstmr_id, org_name AS org_name, legal_form AS lgl_form, industry_code AS indst_code, industry_sector AS indst_sctr, establishment_date AS estbl_date, employee_count AS emply_cnt, annual_revenue AS annl_rvn, revenue_currency AS rvn_crrnc FROM t2s.organizations;
CREATE VIEW t2s_xshort.tb_prdct AS SELECT product_id AS prdct_id, product_code AS prdct_code, product_name AS prdct_name, product_type_code AS prdct_type_code, product_type_name AS prdct_type_name, category AS ctgry, currency_code AS crrnc_code, amortization_type AS amrtz_type, requires_collateral AS rqrs_clltr, requires_guarantor AS rqrs_grntr, min_credit_score AS min_crdt_scr, max_dti_ratio AS max_dti_rt, max_ltv_ratio AS max_ltv_rt, launch_date AS lnch_date, discontinue_date AS dscnt_date, status AS stts, annual_rate AS annl_rate, min_amount AS min_amnt, max_amount AS max_amnt, min_term_months AS min_term_mnths, max_term_months AS max_term_mnths FROM t2s.products;
CREATE VIEW t2s_xshort.tb_loan_applc AS SELECT application_id AS applc_id, application_no AS applc_no, customer_id AS cstmr_id, product_id AS prdct_id, branch_id AS brnch_id, loan_officer_id AS loan_offcr_id, status_code AS stts_code, status_name AS stts_name, channel AS chnnl, requested_amount AS rqstd_amnt, requested_term_months AS rqstd_term_mnths, currency_code AS crrnc_code, purpose_category AS prps_ctgry, declared_income AS dclrd_incm, dti_ratio AS dti_rt, approved_amount AS apprv_amnt, approved_term_months AS apprv_term_mnths, approved_rate AS apprv_rate, credit_score AS crdt_scr, decision_level AS dcsn_lvl, submitted_date AS sbmtt_date, decided_date AS dcdd_date, rejection_reason AS rjctn_rsn FROM t2s.loan_applications;
CREATE VIEW t2s_xshort.tb_lns AS SELECT loan_id AS loan_id, loan_number AS loan_nmbr, application_id AS applc_id, customer_id AS cstmr_id, product_id AS prdct_id, branch_id AS brnch_id, loan_officer_id AS loan_offcr_id, status_code AS stts_code, status_name AS stts_name, is_active_portfolio AS is_actv_prtfl, currency_code AS crrnc_code, principal_amount AS prncp_amnt, interest_rate AS intrs_rate, penalty_rate AS pnlty_rate, effective_rate AS effct_rate, term_months AS term_mnths, amortization_type AS amrtz_type, contract_date AS cntrc_date, disbursement_date AS dsbrs_date, first_payment_date AS frst_pymnt_date, maturity_date AS mtrty_date, closed_date AS clsd_date, disbursed_amount AS dsbrs_amnt, principal_outstanding AS prncp_otstn, interest_outstanding AS intrs_otstn, penalty_outstanding AS pnlty_otstn, fee_outstanding AS fee_otstn, total_outstanding AS ttl_otstn, principal_paid AS prncp_paid, interest_paid AS intrs_paid, penalty_paid AS pnlty_paid, fee_paid AS fee_paid, written_off_amount AS wrttn_off_amnt, overdue_principal AS ovrd_prncp, overdue_interest AS ovrd_intrs, days_past_due AS days_past_due, max_days_past_due AS max_days_past_due, dpd_bucket AS dpd_bckt, classification_code AS clssf_code, classification_name AS clssf_name, provision_rate AS prvsn_rate, is_npl AS is_npl, is_restructured AS is_rstrc, restructure_count AS rstrc_cnt, last_payment_date AS last_pymnt_date, fx_rate_to_mnt AS fx_rate_to_mnt, principal_amount_mnt AS prncp_amnt_mnt, principal_outstanding_mnt AS prncp_otstn_mnt, total_outstanding_mnt AS ttl_otstn_mnt FROM t2s.loans;
CREATE VIEW t2s_xshort.tb_loan_schdl AS SELECT loan_id AS loan_id, installment_no AS instl_no, due_date AS due_date, principal_due AS prncp_due, interest_due AS intrs_due, total_due AS ttl_due, principal_paid AS prncp_paid, interest_paid AS intrs_paid, penalty_charged AS pnlty_chrgd, penalty_paid AS pnlty_paid, status AS stts, paid_date AS paid_date, days_past_due AS days_past_due, schedule_version AS schdl_vrsn FROM t2s.loan_schedule;
CREATE VIEW t2s_xshort.tb_loan_pymnt AS SELECT payment_id AS pymnt_id, payment_no AS pymnt_no, loan_id AS loan_id, customer_id AS cstmr_id, branch_id AS brnch_id, currency_code AS crrnc_code, amount AS amnt, payment_date AS pymnt_date, payment_method AS pymnt_mthd, payment_type AS pymnt_type, allocated_principal AS allct_prncp, allocated_interest AS allct_intrs, allocated_penalty AS allct_pnlty, allocated_fee AS allct_fee, unallocated_amount AS unllc_amnt, status AS stts FROM t2s.loan_payments;
CREATE VIEW t2s_xshort.tb_loan_dpd_hstry AS SELECT loan_id AS loan_id, snapshot_date AS snpsh_date, days_past_due AS days_past_due, dpd_bucket AS dpd_bckt, overdue_principal AS ovrd_prncp, overdue_interest AS ovrd_intrs, overdue_penalty AS ovrd_pnlty, total_outstanding AS ttl_otstn, classification_code AS clssf_code FROM t2s.loan_dpd_history;
CREATE VIEW t2s_xshort.tb_loan_chrgs AS SELECT loan_id AS loan_id, charge_type AS chrg_type, charge_code AS chrg_code, charge_name AS chrg_name, currency_code AS crrnc_code, amount AS amnt, charged_date AS chrgd_date, paid_amount AS paid_amnt, waived_amount AS wvd_amnt, status AS stts, days_overdue AS days_ovrd FROM t2s.loan_charges;
CREATE VIEW t2s_xshort.tb_loan_rstrc AS SELECT loan_id AS loan_id, restructure_no AS rstrc_no, restructure_type AS rstrc_type, reason AS rsn, old_principal AS old_prncp, new_principal AS new_prncp, old_rate AS old_rate, new_rate AS new_rate, old_term_months AS old_term_mnths, new_term_months AS new_term_mnths, old_maturity_date AS old_mtrty_date, new_maturity_date AS new_mtrty_date, effective_date AS effct_date, status AS stts FROM t2s.loan_restructures;
CREATE VIEW t2s_xshort.tb_loan_wrtff AS SELECT loan_id AS loan_id, writeoff_date AS wrtff_date, principal_amount AS prncp_amnt, interest_amount AS intrs_amnt, penalty_amount AS pnlty_amnt, fee_amount AS fee_amnt, total_amount AS ttl_amnt, writeoff_type AS wrtff_type, recovered_amount AS rcvrd_amnt FROM t2s.loan_writeoffs;
CREATE VIEW t2s_xshort.tb_clltr AS SELECT collateral_id AS clltr_id, collateral_number AS clltr_nmbr, collateral_type_code AS clltr_type_code, collateral_type_name AS clltr_type_name, collateral_category AS clltr_ctgry, owner_customer_id AS ownr_cstmr_id, branch_id AS brnch_id, market_value AS mrkt_vl, forced_sale_value AS frcd_sale_vl, accepted_value AS accpt_vl, currency_code AS crrnc_code, valuation_date AS vltn_date, next_valuation_date AS next_vltn_date, is_insured AS is_insrd, encumbrance_status AS encmb_stts, status AS stts FROM t2s.collaterals;
CREATE VIEW t2s_xshort.tb_loan_clltr AS SELECT loan_id AS loan_id, collateral_id AS clltr_id, currency_code AS crrnc_code, allocated_amount AS allct_amnt, ltv_ratio AS ltv_rt, pledge_date AS pldg_date, release_date AS rls_date, status AS stts FROM t2s.loan_collaterals;
CREATE VIEW t2s_xshort.tb_loan_grntr AS SELECT loan_id AS loan_id, guarantor_id AS grntr_id, guarantor_type AS grntr_type, is_existing_customer AS is_exstn_cstmr, guarantor_customer_id AS grntr_cstmr_id, currency_code AS crrnc_code, guarantee_amount AS grnt_amnt, guarantee_pct AS grnt_pct, liability_type AS lblty_type, valid_from AS vld_from, valid_to AS vld_to, called_date AS clld_date, called_amount AS clld_amnt, recovered_amount AS rcvrd_amnt, status AS stts FROM t2s.loan_guarantors;
CREATE VIEW t2s_xshort.tb_accnt AS SELECT account_id AS accnt_id, customer_id AS cstmr_id, branch_id AS brnch_id, product_id AS prdct_id, account_type_code AS accnt_type_code, account_type_name AS accnt_type_name, currency_code AS crrnc_code, current_balance AS crrnt_blnc, available_balance AS avlbl_blnc, hold_amount AS hold_amnt, status AS stts, is_dormant AS is_drmnt, opened_date AS opnd_date, closed_date AS clsd_date, last_transaction_date AS last_trnsc_date FROM t2s.accounts;
CREATE VIEW t2s_xshort.tb_trnsc AS SELECT transaction_id AS trnsc_id, transaction_no AS trnsc_no, account_id AS accnt_id, customer_id AS cstmr_id, branch_id AS brnch_id, transaction_type_code AS trnsc_type_code, transaction_type_name AS trnsc_type_name, category AS ctgry, channel_code AS chnnl_code, channel_name AS chnnl_name, status_code AS stts_code, direction AS drctn, amount AS amnt, fee_amount AS fee_amnt, currency_code AS crrnc_code, amount_mnt AS amnt_mnt, transaction_date AS trnsc_date, value_date AS vl_date FROM t2s.transactions;
CREATE VIEW t2s_xshort.tb_accnt_blncs_mnthl AS SELECT account_id AS accnt_id, balance_date AS blnc_date, opening_balance AS opnng_blnc, total_debit AS ttl_dbt, total_credit AS ttl_crdt, closing_balance AS clsng_blnc, transaction_count AS trnsc_cnt, currency_code AS crrnc_code, closing_balance_mnt AS clsng_blnc_mnt FROM t2s.account_balances_monthly;
CREATE VIEW t2s_xshort.tb_dpsts AS SELECT deposit_id AS dpst_id, deposit_number AS dpst_nmbr, account_id AS accnt_id, customer_id AS cstmr_id, product_id AS prdct_id, branch_id AS brnch_id, currency_code AS crrnc_code, deposit_type AS dpst_type, principal_amount AS prncp_amnt, current_balance AS crrnt_blnc, interest_rate AS intrs_rate, interest_method AS intrs_mthd, term_months AS term_mnths, accrued_interest AS accrd_intrs, paid_interest AS paid_intrs, withholding_tax_paid AS wthhl_tax_paid, opened_date AS opnd_date, maturity_date AS mtrty_date, closed_date AS clsd_date, auto_renew AS auto_rnw, renewal_count AS rnwl_cnt, is_pledged AS is_pldgd, status AS stts, current_balance_mnt AS crrnt_blnc_mnt FROM t2s.deposits;
CREATE VIEW t2s_xshort.tb_cllct_css AS SELECT case_id AS case_id, case_no AS case_no, loan_id AS loan_id, customer_id AS cstmr_id, branch_id AS brnch_id, stage_code AS stg_code, stage_name AS stg_name, currency_code AS crrnc_code, opened_date AS opnd_date, dpd_at_open AS dpd_at_open, current_dpd AS crrnt_dpd, outstanding_at_open AS otstn_at_open, current_outstanding AS crrnt_otstn, overdue_amount AS ovrd_amnt, collected_amount AS cllct_amnt, assigned_to AS assgn_to, agency_code AS agncy_code, agency_name AS agncy_name, priority AS prrty, status AS stts, closed_date AS clsd_date, close_reason AS cls_rsn FROM t2s.collection_cases;
CREATE VIEW t2s_xshort.tb_cllct_actns AS SELECT action_id AS actn_id, case_id AS case_id, action_code AS actn_code, action_name AS actn_name, channel AS chnnl, action_date AS actn_date, performed_by AS prfrm_by, agency_code AS agncy_code, contact_result AS cntct_rslt, cost_amount AS cost_amnt FROM t2s.collection_actions;
CREATE VIEW t2s_xshort.tb_cllct_prmss AS SELECT promise_id AS prms_id, case_id AS case_id, currency_code AS crrnc_code, promised_amount AS prmsd_amnt, promised_date AS prmsd_date, paid_amount AS paid_amnt, paid_date AS paid_date, status AS stts FROM t2s.collection_promises;
CREATE VIEW t2s_xshort.tb_crdt_scrs AS SELECT score_id AS scr_id, customer_id AS cstmr_id, application_id AS applc_id, model_code AS mdl_code, model_name AS mdl_name, score AS scr, risk_grade_code AS risk_grd_code, risk_grade_name AS risk_grd_name, pd_estimate AS pd_estmt, decision_hint AS dcsn_hint, score_type AS scr_type, scored_date AS scrd_date FROM t2s.credit_scores;
CREATE VIEW t2s_xshort.tb_aml_alrts AS SELECT alert_id AS alrt_id, alert_no AS alrt_no, rule_code AS rule_code, rule_name AS rule_name, customer_id AS cstmr_id, alert_amount AS alrt_amnt, currency_code AS crrnc_code, severity AS svrty, status AS stts, detected_date AS dtctd_date, closed_date AS clsd_date, str_reported AS str_rprtd FROM t2s.aml_alerts;
CREATE VIEW t2s_xshort.tb_gl_entrs AS SELECT entry_no AS entry_no, line_no AS line_no, posting_date AS pstng_date, period_code AS prd_code, fiscal_year AS fscl_year, branch_id AS brnch_id, journal_code AS jrnl_code, journal_name AS jrnl_name, account_code AS accnt_code, account_name_mn AS accnt_name_mn, account_type AS accnt_type, dr_cr AS dr_cr, amount AS amnt, currency_code AS crrnc_code, amount_mnt AS amnt_mnt, source_system AS src_systm, entry_status AS entry_stts FROM t2s.gl_entries;
CREATE VIEW t2s_xshort.tb_exchn_rts AS SELECT currency_code AS crrnc_code, rate_date AS rate_date, buy_rate AS buy_rate, sell_rate AS sell_rate, mid_rate AS mid_rate FROM t2s.exchange_rates;
GRANT USAGE ON SCHEMA t2s_xshort TO t2s_bot; GRANT SELECT ON ALL TABLES IN SCHEMA t2s_xshort TO t2s_bot;
